// Location map engine — MapLibre GL on MapTiler vector tiles, brand style from
// the repo. This is the AGP starter's ServiceAreaMap approach (see
// agp-astro-starter → CLAUDE.md → Maps) generalised so every location page can
// pass its own pins: county pages, state hubs, office pages, rental geo pages.
//
// Used by src/components/LocationMap.astro (static pages) and
// src/components/LocationMap.jsx (inside the React rental islands). Both render
// a container and hand it here; nothing else touches MapLibre directly.
//
// Style files: src/data/map-style-{light,dark}.json, generated by
// scripts/build_map_style.py. Coordinates: src/data/location-maps.ts.
//
// Key: PUBLIC_MAPTILER_KEY (publishable, origin-restricted in MapTiler Cloud)
// is injected into the style's tile/font URLs at runtime. Without a key the map
// falls back to keyless OpenStreetMap raster tiles, retoned by CSS, and logs a
// console warning — fine for a preview, not for launch.
//
// Weight: MapLibre (~275 KB gzipped) and the style load only when a map scrolls
// within 300px of the viewport; first paint pays nothing.

export type MapTheme = 'light' | 'dark';

export interface MapPin {
  name: string;
  lat: number;
  lng: number;
  /** city (teal dot, default) · seat (gold dot — county seat / anchor) · office (gold teardrop with popup) */
  kind?: 'city' | 'seat' | 'office';
  /** One-line context shown in the tooltip / popup (e.g. "County seat", "Townhome HOAs · BWI corridor"). */
  note?: string;
  /** Offices: the street address shown in the popup, also used for the directions link. */
  address?: string;
  phone?: string;
  /** Optional page to link from the popup. */
  href?: string;
  /** Force the label to one side of the dot. Default: right, auto-flipped when it would cover another pin. */
  labelSide?: 'left' | 'right';
}

export interface LocationMapConfig {
  theme?: MapTheme;
  pins: MapPin[];
  /** fitBounds padding in px (default 44). */
  padding?: number;
  /** Zoom cap when fitting to the pins (default 11). Lower for state/region maps. */
  maxZoom?: number;
  /** Zoom used when there is only one pin (default 12). */
  singleZoom?: number;
  /** Hide pin labels below this zoom so region maps stay legible (default 8.2). */
  labelMinZoom?: number;
}

type MapLibreModule = typeof import('maplibre-gl');

const PLACEHOLDER = '__MAPTILER_KEY__';
const OSM_FALLBACK = {
  version: 8,
  sources: {
    osm: {
      type: 'raster',
      tiles: ['a', 'b', 'c'].map((s) => `https://${s}.tile.openstreetmap.org/{z}/{x}/{y}.png`),
      tileSize: 256,
      maxzoom: 19,
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
  },
  layers: [{ id: 'osm', type: 'raster', source: 'osm' }],
};

const esc = (s: string) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] as string));

const directionsUrl = (p: MapPin) =>
  'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(p.address || `${p.lat},${p.lng}`);

const pinSvg = () =>
  `<svg viewBox="0 0 24 34" width="26" height="36" aria-hidden="true">
    <path d="M12 33C4.8 22.6 1 17.2 1 12a11 11 0 0 1 22 0c0 5.2-3.8 10.6-11 21Z" fill="#BFAC5F" stroke="#FEFCF8" stroke-width="1.6"/>
    <circle cx="12" cy="12" r="4.1" fill="#172325"/>
  </svg>`;

async function loadStyle(theme: MapTheme, key: string | undefined) {
  if (!key) return null;
  const mod = theme === 'light'
    ? await import('../data/map-style-light.json')
    : await import('../data/map-style-dark.json');
  return JSON.parse(JSON.stringify(mod.default).split(PLACEHOLDER).join(key));
}

/** Mount a map into `el`. Resolves once MapLibre has loaded the style. */
export async function mountLocationMap(el: HTMLElement, cfg: LocationMapConfig): Promise<void> {
  const theme: MapTheme = cfg.theme ?? 'dark';
  const pins = cfg.pins ?? [];
  const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const key = import.meta.env.PUBLIC_MAPTILER_KEY as string | undefined;

  const [{ default: maplibregl }, brandStyle] = await Promise.all([
    import('maplibre-gl') as Promise<MapLibreModule>,
    loadStyle(theme, key),
  ]);
  if (!el.isConnected) return; // island unmounted while we were loading

  let style: any = brandStyle;
  if (!style) {
    el.classList.add('is-osm');
    console.warn('[LocationMap] PUBLIC_MAPTILER_KEY is not set — falling back to keyless OpenStreetMap tiles. Set the key in Vercel before launch.');
    style = OSM_FALLBACK;
  }
  let onOsm = !brandStyle;

  const first = pins[0];
  const map = new maplibregl.Map({
    container: el,
    style,
    center: first ? [first.lng, first.lat] : [-76.6, 39.1],
    zoom: cfg.singleZoom ?? 12,
    scrollZoom: false,          // page scroll must not be hijacked; a click unlocks the wheel
    dragRotate: false,
    pitchWithRotate: false,
    touchPitch: false,
    attributionControl: false,
    fadeDuration: still ? 0 : 300,
  });
  (el as any).__twMap = map;
  // The key is origin-restricted in MapTiler Cloud. If this page's origin is
  // not on the key's allow-list (a preview URL, a new domain), MapTiler answers
  // 401/403 and the map would stay blank — swap to the keyless fallback instead
  // of showing nothing. The DOM markers survive the style change.
  map.on('error', (ev: any) => {
    const status = ev?.error?.status;
    if (onOsm || (status !== 401 && status !== 403)) return;
    onOsm = true;
    el.classList.add('is-osm');
    console.warn(`[LocationMap] MapTiler rejected this origin (${status}) — add ${location.origin} to the key's Allowed HTTP Origins. Falling back to OpenStreetMap tiles.`);
    map.setStyle(OSM_FALLBACK as any);
  });
  map.touchZoomRotate.disableRotation();
  map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
  map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-right');
  map.once('click', () => map.scrollZoom.enable());

  if (pins.length > 1) {
    const b = new maplibregl.LngLatBounds([first.lng, first.lat], [first.lng, first.lat]);
    pins.forEach((p) => b.extend([p.lng, p.lat]));
    map.fitBounds(b, { padding: cfg.padding ?? 44, duration: 0, maxZoom: cfg.maxZoom ?? 11 });
  }

  // Labels hide at low zoom so a state/region map isn't a wall of text.
  const labelMin = cfg.labelMinZoom ?? 8.2;
  const syncCompact = () => el.classList.toggle('is-compact', map.getZoom() < labelMin);
  map.on('zoom', syncCompact);
  syncCompact();

  const popupFor = (p: MapPin) => {
    const bits = [`<strong>${esc(p.name)}</strong>`];
    if (p.note) bits.push(esc(p.note));
    if (p.address) bits.push(esc(p.address));
    if (p.phone) bits.push(`<a href="tel:${esc(p.phone.replace(/[^\d+]/g, ''))}">${esc(p.phone)}</a>`);
    const links: string[] = [];
    if (p.address) links.push(`<a href="${directionsUrl(p)}" target="_blank" rel="noopener">Get directions</a>`);
    if (p.href) links.push(`<a href="${esc(p.href)}">View page</a>`);
    if (links.length) bits.push(links.join(' · '));
    return new maplibregl.Popup({ offset: p.kind === 'office' ? [0, -34] : [0, -8], closeButton: true, maxWidth: '260px' })
      .setHTML(bits.join('<br>'));
  };

  type Labelled = { pin: MapPin; node: HTMLElement };
  const labelled: Labelled[] = [];
  const officeNodes: HTMLElement[] = []; // office markers: labels must dodge these too

  pins.forEach((p) => {
    const node = document.createElement('div');
    if (p.kind === 'office') {
      node.className = 'tw-lmap-office';
      node.innerHTML = `<span class="ring" aria-hidden="true"></span>${pinSvg()}<span class="label">${esc(p.name)}</span>`;
      node.setAttribute('role', 'button');
      node.setAttribute('aria-label', p.address ? `${p.name}, ${p.address}` : p.name);
      node.tabIndex = 0;
      officeNodes.push(node);
      const popup = popupFor(p);
      new maplibregl.Marker({ element: node, anchor: 'bottom' }).setLngLat([p.lng, p.lat]).setPopup(popup).addTo(map);
      node.addEventListener('keydown', (ev) => {
        if (ev.key !== 'Enter' && ev.key !== ' ') return;
        ev.preventDefault();
        popup.isOpen() ? popup.remove() : popup.setLngLat([p.lng, p.lat]).addTo(map);
      });
      return;
    }
    node.className = 'tw-lmap-pin' + (p.kind === 'seat' ? ' is-seat' : '') + (p.labelSide === 'left' ? ' is-left' : '');
    node.innerHTML = `<span class="dot" aria-hidden="true"></span><span class="label">${esc(p.name)}</span>`;
    if (p.note) node.title = p.note;
    // The element is just the dot, centred on the coordinate; the label is
    // positioned off it by CSS so it can flip sides without re-anchoring.
    const marker = new maplibregl.Marker({ element: node, anchor: 'center' })
      .setLngLat([p.lng, p.lat]).addTo(map);
    labelled.push({ pin: p, node });
    if (p.note || p.href) {
      node.setAttribute('role', 'button');
      node.setAttribute('aria-label', p.note ? `${p.name} — ${p.note}` : p.name);
      node.tabIndex = 0;
      marker.setPopup(popupFor(p));
      node.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); marker.togglePopup(); }
      });
    }
  });

  // Label placement. Each label tries right of its dot, then left, then below,
  // and takes the first spot that neither leaves the map nor covers another
  // marker or an already-placed label. Pins are placed west to east so a label
  // only has to dodge what is already on the map. Geometry comes from the
  // marker elements themselves, so office teardrops block by their drawn size.
  type Box = { x1: number; x2: number; y1: number; y2: number };
  const overlaps = (a: Box, b: Box) => a.x2 > b.x1 && a.x1 < b.x2 && a.y2 > b.y1 && a.y1 < b.y2;
  const textWidth = (p: MapPin) => p.name.length * (p.kind === 'seat' ? 7 : 6.4) + 6;
  const layoutLabels = () => {
    const cr = el.getBoundingClientRect();
    const rel = (n: HTMLElement): Box => {
      const r = n.getBoundingClientRect();
      return { x1: r.left - cr.left, x2: r.right - cr.left, y1: r.top - cr.top, y2: r.bottom - cr.top };
    };
    const pts = labelled.map((e) => ({ e, r: rel(e.node) })).sort((a, b) => a.r.x1 - b.r.x1);
    const blocks: Box[] = [
      ...pts.map((x) => x.r),
      // teardrop + the label row beneath its tip (labels are wider than the pin)
      ...officeNodes.map((n) => { const r = rel(n); return { x1: r.x1 - 30, x2: r.x2 + 30, y1: r.y1, y2: r.y2 + 16 }; }),
      // the zoom control in the top-right corner
      ...Array.from(el.querySelectorAll<HTMLElement>('.maplibregl-ctrl-top-right')).map(rel),
    ];
    const inside = (b: Box) => b.x1 >= 2 && b.x2 <= cr.width - 2 && b.y1 >= 0 && b.y2 <= cr.height;
    for (const a of pts) {
      const w = textWidth(a.e.pin);
      const cx = (a.r.x1 + a.r.x2) / 2, cy = (a.r.y1 + a.r.y2) / 2;
      const boxes: Record<string, Box> = {
        right: { x1: a.r.x2 + 4, x2: a.r.x2 + 4 + w, y1: cy - 7, y2: cy + 7 },
        left:  { x1: a.r.x1 - 4 - w, x2: a.r.x1 - 4, y1: cy - 7, y2: cy + 7 },
        below: { x1: cx - w / 2, x2: cx + w / 2, y1: a.r.y2 + 2, y2: a.r.y2 + 15 },
      };
      const free = (k: string) => inside(boxes[k]) && !blocks.some((b) => b !== a.r && overlaps(boxes[k], b));
      const order = a.e.pin.labelSide ? [a.e.pin.labelSide] : ['right', 'left', 'below'];
      let side = order.find(free) ?? (inside(boxes.right) ? 'right' : inside(boxes.left) ? 'left' : 'below');
      a.e.node.classList.toggle('is-left', side === 'left');
      a.e.node.classList.toggle('is-below', side === 'below');
      blocks.push(boxes[side]);
    }
  };
  (el as any).__twLayout = layoutLabels; // handy from devtools: $0.__twLayout()
  map.on('moveend', layoutLabels);

  map.on('load', () => { layoutLabels(); el.classList.add('is-ready'); });
}

/** Mount when the element is within 300px of the viewport (once). */
export function observeLocationMap(el: HTMLElement, cfg: LocationMapConfig): void {
  if ((el as any).__twMapQueued) return;
  (el as any).__twMapQueued = true;
  const go = () => { mountLocationMap(el, cfg).catch((e) => console.error('[LocationMap]', e)); };
  if (!('IntersectionObserver' in window)) { go(); return; }
  const io = new IntersectionObserver((entries) => {
    entries.forEach((en) => { if (!en.isIntersecting) return; io.disconnect(); go(); });
  }, { rootMargin: '300px 0px' });
  io.observe(el);
}

/** Scan the page for `[data-location-map]` containers (LocationMap.astro). */
export function observeLocationMaps(root: ParentNode = document): void {
  root.querySelectorAll<HTMLElement>('[data-location-map]').forEach((el) => {
    try {
      const cfg = JSON.parse(el.dataset.config || '{}') as LocationMapConfig;
      observeLocationMap(el, cfg);
    } catch (e) {
      console.error('[LocationMap] bad data-config', e);
    }
  });
}

/** Tear a map down (React islands call this on unmount). */
export function destroyLocationMap(el: HTMLElement): void {
  const map = (el as any).__twMap;
  if (map) { map.remove(); delete (el as any).__twMap; }
  delete (el as any).__twMapQueued;
}
